css:
.m-pull-cord-lamp {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: #111113;
  cursor: pointer;
  outline: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}
.m-pull-cord-lamp:focus-visible {
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.32);
}
.m-pull-cord-lamp__ambient {
  position: absolute;
  inset: 0;
  background: radial-gradient(62% 72% at 50% 44%, rgba(255, 243, 220, 0.14), rgba(255, 243, 220, 0) 70%);
  opacity: 0;
  transition: opacity 0.2s ease-out;
  pointer-events: none;
}
.m-pull-cord-lamp__svg {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}
.m-pull-cord-lamp__beam,
.m-pull-cord-lamp__halo {
  opacity: 0;
  transition: opacity 0.16s ease-out;
}
.m-pull-cord-lamp__dome {
  fill: #5c5c61;
  transition: fill 0.2s ease-out;
}
.m-pull-cord-lamp__bulb {
  fill: #38383c;
  transition: fill 0.12s ease-out;
}
.m-pull-cord-lamp__cord {
  fill: none;
  stroke: #86868c;
  stroke-width: 1.6;
  stroke-linecap: round;
  transition: stroke 0.25s ease-out;
}
.m-pull-cord-lamp__bead rect {
  fill: #96969c;
  transition: fill 0.25s ease-out;
}
.m-pull-cord-lamp__grip {
  fill: transparent;
  cursor: grab;
  touch-action: none;
}
.m-pull-cord-lamp.is-dragging,
.m-pull-cord-lamp.is-dragging .m-pull-cord-lamp__grip {
  cursor: grabbing;
}
.m-pull-cord-lamp.is-on .m-pull-cord-lamp__ambient {
  opacity: 1;
  transition: opacity 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.m-pull-cord-lamp.is-on .m-pull-cord-lamp__beam,
.m-pull-cord-lamp.is-on .m-pull-cord-lamp__halo {
  opacity: 1;
  transition: opacity 0.32s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.m-pull-cord-lamp.is-on .m-pull-cord-lamp__dome {
  fill: #a9a9ae;
}
.m-pull-cord-lamp.is-on .m-pull-cord-lamp__bulb {
  fill: #ffffff;
}
.m-pull-cord-lamp.is-on .m-pull-cord-lamp__cord {
  stroke: #b4b4ba;
}
.m-pull-cord-lamp.is-on .m-pull-cord-lamp__bead rect {
  fill: #cdcdd2;
}

js:
var el = root.querySelector('.m-pull-cord-lamp');
if (!el) return;
var svg = el.querySelector('svg');
var pick = function (n) { return el.querySelector('.m-pull-cord-lamp__' + n); };
var lamp = pick('lamp'), cord = pick('cord'), bead = pick('bead'), grip = pick('grip');

// Give gradients/filters instance-unique ids so several lamps can share a page.
var uid = Math.random().toString(36).slice(2, 7);
Array.prototype.forEach.call(svg.querySelectorAll('[id]'), function (n) { n.id += '-' + uid; });
Array.prototype.forEach.call(svg.querySelectorAll('[fill^="url("],[filter^="url("]'), function (n) {
  ['fill', 'filter'].forEach(function (a) {
    var v = n.getAttribute(a);
    if (v && v.indexOf('url(#') === 0) n.setAttribute(a, v.replace(')', '-' + uid + ')'));
  });
});

var AX = 211, AY = 64, LEN = 100;      // cord anchor + rest length (viewBox units)
var MAX = 60, CLICK = 26;              // max elastic stretch, switch threshold
var bx = 0, by = 0, vx = 0, vy = 0;    // bead displacement from rest + velocity
var dy = 0, dv = 0;                    // shade dip (it gets tugged by the cord)
var on = false, latch = false, drag = null, pulse = null, touched = false;
var raf = 0, running = false, last = 0, seen = false, dead = false, quietUntil = 0;

function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }

function toggle() {
  on = !on;
  el.classList.toggle('is-on', on);
  el.setAttribute('aria-pressed', on ? 'true' : 'false');
  dv += 60; // mechanical click: the shade jolts
}

function step(h) {
  if (drag) {
    var f = Math.pow(0.0005, h); // stale pointer velocity bleeds off
    vx *= f; vy *= f;
  } else {
    if (pulse) {
      pulse.t += h;
      var k = Math.min(1, pulse.t / 0.17), e = 1 - Math.pow(1 - k, 3);
      by = pulse.from + (pulse.to - pulse.from) * e;
      vy = 0;
      if (k >= 1) pulse = null;
    } else {
      vy += (-170 * by - 7.5 * vy) * h; // underdamped: zeta ~ 0.29
      by += vy * h;
    }
    vx += (-38 * bx - 3 * vx) * h;      // slower pendulum sway
    bx += vx * h;
  }
  if (!latch && by > CLICK) { latch = true; toggle(); }
  else if (latch && by < CLICK * 0.42) latch = false;
  var tug = Math.max(0, by) * 0.08;
  dv += (-320 * (dy - tug) - 15 * dv) * h;
  dy += dv * h;
}

function render() {
  var rot = bx * 0.05, rad = rot * Math.PI / 180;
  var sx = AX - rad * (AY - 36), sy = AY + dy + rad * (AX - 180);
  var ex = AX + bx, ey = AY + LEN + by;
  var slack = Math.max(0, -by);
  var lag = clamp(vx * 0.04, -14, 14);
  var cx = sx + (ex - sx) * 0.5 - lag + slack * 0.55 * (bx < 0 ? -1 : 1);
  var cy = sy + (ey - sy) * 0.55;
  var ang = Math.atan2(ex - cx, ey - cy) * 180 / Math.PI;
  lamp.setAttribute('transform', 'translate(0 ' + dy.toFixed(2) + ') rotate(' + rot.toFixed(2) + ' 180 36)');
  cord.setAttribute('d', 'M' + sx.toFixed(2) + ' ' + sy.toFixed(2) + 'Q' + cx.toFixed(2) + ' ' + cy.toFixed(2) + ' ' + ex.toFixed(2) + ' ' + ey.toFixed(2));
  bead.setAttribute('transform', 'translate(' + ex.toFixed(2) + ' ' + ey.toFixed(2) + ') rotate(' + (-ang).toFixed(2) + ')');
  grip.setAttribute('cx', ex.toFixed(1));
  grip.setAttribute('cy', (ey + 10).toFixed(1));
}

function frame(now) {
  raf = 0;
  if (dead) return;
  if (el.isConnected) seen = true; else if (seen) { dispose(); return; }
  var dt = clamp((now - last) / 1000, 0.001, 0.034);
  last = now;
  for (var n = Math.ceil(dt / 0.004), h = dt / n; n-- > 0;) step(h);
  render();
  var energy = Math.abs(by) + Math.abs(bx) + Math.abs(dy) + (Math.abs(vy) + Math.abs(vx) + Math.abs(dv)) * 0.05;
  if (drag || pulse || energy > 0.03) raf = requestAnimationFrame(frame);
  else { running = false; bx = by = vx = vy = dy = dv = 0; render(); }
}

function wake() {
  if (dead || raf) return;
  if (!running) { running = true; last = performance.now(); }
  raf = requestAnimationFrame(frame);
}

function tug() {
  pulse = { t: 0, from: by, to: 38 };
  vx += (Math.random() < 0.5 ? -1 : 1) * 22;
  wake();
}

function unit() {
  var r = svg.getBoundingClientRect();
  return Math.min(r.width / 360, r.height / 260) || 1;
}

function onDown(e) {
  if (e.button) return;
  touched = true;
  pulse = null;
  drag = { id: e.pointerId, x: e.clientX, y: e.clientY, bx: bx, by: by, moved: 0, u: unit(), t: performance.now() };
  try { grip.setPointerCapture(e.pointerId); } catch (err) {}
  el.classList.add('is-dragging');
  e.preventDefault();
  wake();
}

function onMove(e) {
  if (!drag || e.pointerId !== drag.id) return;
  var rx = (e.clientX - drag.x) / drag.u + drag.bx;
  var ry = (e.clientY - drag.y) / drag.u + drag.by;
  drag.moved = Math.max(drag.moved, Math.abs(e.clientX - drag.x) + Math.abs(e.clientY - drag.y));
  // Rubber-band: the further you pull, the less the cord gives.
  var nx = 34 * Math.tanh(rx / 70);
  var ny = ry > 0 ? MAX * (1 - Math.exp(-ry / MAX)) : -10 * (1 - Math.exp(ry / 30));
  var now = performance.now(), dt = Math.max(0.008, (now - drag.t) / 1000);
  drag.t = now;
  vx = clamp((nx - bx) / dt, -500, 500);
  vy = clamp((ny - by) / dt, -700, 700);
  bx = nx; by = ny;
  wake();
}

function onUp(e) {
  if (!drag || (e && e.pointerId !== drag.id)) return;
  var tap = drag.moved < 4;
  drag = null;
  el.classList.remove('is-dragging');
  quietUntil = performance.now() + 350; // swallow the click that follows a drag
  if (tap) tug();
  wake();
}

function onClick() {
  if (performance.now() < quietUntil) return;
  touched = true;
  tug();
}

function onKey(e) {
  if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); touched = true; if (!e.repeat) tug(); }
}

grip.addEventListener('pointerdown', onDown);
grip.addEventListener('pointermove', onMove);
grip.addEventListener('pointerup', onUp);
grip.addEventListener('pointercancel', onUp);
grip.addEventListener('lostpointercapture', onUp);
el.addEventListener('click', onClick);
el.addEventListener('keydown', onKey);

// Ambient demo: one gentle pull every 4.5s until the user touches it.
var first = setTimeout(function () { if (!touched && !dead) tug(); }, 900);
var auto = setInterval(function () {
  if (seen && !el.isConnected) { dispose(); return; }
  if (!touched && !document.hidden) tug();
}, 4500);

function dispose() {
  dead = true;
  clearTimeout(first);
  clearInterval(auto);
  if (raf) cancelAnimationFrame(raf);
}

render();
return dispose;

css:
.m-hold-to-confirm {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background: #111113;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Inter", "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
}
.m-hold-to-confirm__scaler {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.m-hold-to-confirm__pill {
  position: relative;
  display: block;
  box-sizing: border-box;
  width: 196px;
  height: 50px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: #2a2a2d;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.09), inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 10px 26px rgba(0, 0, 0, 0.38);
  color: #f4f4f5;
  font: inherit;
  cursor: pointer;
  overflow: hidden;
  outline: none;
  appearance: none;
  -webkit-appearance: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  -webkit-tap-highlight-color: transparent;
  will-change: transform, width;
}
.m-hold-to-confirm__pill:focus-visible {
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.09), 0 0 0 3px rgba(255, 255, 255, 0.3), 0 10px 26px rgba(0, 0, 0, 0.38);
}
.m-hold-to-confirm__layer {
  position: absolute;
  inset: 0;
  border-radius: inherit;
}
.m-hold-to-confirm__layer--fill {
  background: #ececee;
  color: #151517;
  clip-path: inset(0 100% 0 0);
}
.m-hold-to-confirm__label {
  position: absolute;
  left: 50%;
  top: 50%;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  transform: translate(-50%, -50%);
  white-space: nowrap;
  font-size: 15px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.01em;
  transition: opacity 0.22s ease 0.12s;
}
.m-hold-to-confirm__label svg {
  flex: none;
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.m-hold-to-confirm__check {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 24px;
  height: 24px;
  margin: -12px 0 0 -12px;
  opacity: 0;
  transition: opacity 0.1s ease;
}
.m-hold-to-confirm__check path {
  fill: none;
  stroke: #151517;
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 16;
  stroke-dashoffset: 16;
}
.m-hold-to-confirm__ring {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 50px;
  height: 50px;
  margin: -25px 0 0 -25px;
  border-radius: 50%;
  box-shadow: 0 0 0 1.5px rgba(255, 255, 255, 0.6);
  opacity: 0;
  pointer-events: none;
}
.m-hold-to-confirm.is-done .m-hold-to-confirm__label {
  opacity: 0;
  transition: opacity 0.1s ease;
}
.m-hold-to-confirm.is-done .m-hold-to-confirm__check {
  opacity: 1;
}
.m-hold-to-confirm.is-done .m-hold-to-confirm__check path {
  stroke-dashoffset: 0;
  transition: stroke-dashoffset 0.32s cubic-bezier(0.3, 0.9, 0.3, 1) 0.16s;
}
.m-hold-to-confirm.is-done .m-hold-to-confirm__ring {
  animation: m-hold-to-confirm-ring 0.7s cubic-bezier(0.2, 0.7, 0.2, 1) 0.1s both;
}
@keyframes m-hold-to-confirm-ring {
  0% { opacity: 0.6; transform: scale(0.9); }
  100% { opacity: 0; transform: scale(1.9); }
}

js:
var el = root.querySelector('.m-hold-to-confirm');
if (!el) return;
var pick = function (n) { return el.querySelector('.m-hold-to-confirm__' + n); };
var scaler = pick('scaler'), pill = pick('pill'), fill = pick('layer--fill'), label = pick('label');

var HOLD = 0.9, CANCEL = 0.26, DONE_MS = 1600;
var H = 50, fullW = 196;
var t = 0;                    // linear hold time 0..1
var s = 1, sv = 0;            // press scale spring
var w = fullW, wv = 0;        // width spring (pill <-> circle)
var state = 'idle';           // idle | done
var holding = false, auto = false, hover = false;
var doneAt = 0, idleAt = performance.now(), lastTouch = -1e9;
var last = performance.now(), raf = 0, seen = false, dead = false;
var shownP = -1, shownW = -1, shownS = -1;

// Fast start, tightening finish: the last 10% of the sweep takes ~25% of the hold.
function ease(x) { return 1 - Math.pow(1 - x, 1.6); }

function measure() {
  var lw = label.offsetWidth;
  if (lw > 0) {
    var nw = Math.round(lw + 46);
    if (state !== 'done' && Math.abs(w - fullW) < 0.5) w = nw;
    fullW = nw;
  }
  var cw = el.clientWidth, ch = el.clientHeight;
  if (cw > 0 && ch > 0) {
    var k = Math.max(1, Math.min(1.4, Math.min(cw / 380, ch / 250)));
    scaler.style.transform = k > 1.001 ? 'scale(' + k.toFixed(3) + ')' : '';
  }
}

function frame(now) {
  raf = 0;
  if (dead) return;
  if (el.isConnected) seen = true; else if (seen) { dispose(); return; }
  raf = requestAnimationFrame(frame);
  var dt = Math.min(0.034, (now - last) / 1000);
  last = now;
  if (dt <= 0) return;

  if (state === 'done') {
    if (now - doneAt > DONE_MS) {
      state = 'idle';
      t = 0.999; // un-sweep while the circle springs back into a pill
      el.classList.remove('is-done');
    }
  } else {
    if (!holding && !hover && t === 0 && now - idleAt > 1200 && now - lastTouch > 2600 && !document.hidden) {
      holding = auto = true; // ambient demo hold
    }
    var prev = t;
    t = holding ? Math.min(1, t + dt / HOLD) : Math.max(0, t - dt / CANCEL);
    if (prev > 0 && t === 0) idleAt = now;
    if (t >= 1) {
      state = 'done';
      holding = auto = false;
      doneAt = now;
      sv += 4.2; // release kick -> crisp bounce
      el.classList.add('is-done');
    }
  }

  var done = state === 'done';
  var p = done ? 1 : ease(t);
  var sT = done ? 1 : holding ? 0.96 - 0.012 * p : 1;
  var wT = done ? H : fullW;
  for (var n = 4, h = dt / 4; n-- > 0;) {
    sv += (-420 * (s - sT) - 24 * sv) * h; s += sv * h;
    wv += (-360 * (w - wT) - 27 * wv) * h; w += wv * h;
  }

  var pv = Math.round(p * 1000) / 10, wr = Math.round(w * 10) / 10, sr = Math.round(s * 1000) / 1000;
  if (pv !== shownP) { fill.style.clipPath = 'inset(0 ' + (100 - pv).toFixed(1) + '% 0 0)'; shownP = pv; }
  if (wr !== shownW) { pill.style.width = wr + 'px'; shownW = wr; }
  if (sr !== shownS) { pill.style.transform = 'scale(' + sr + ')'; shownS = sr; }
}

function press() {
  if (state === 'done') return;
  holding = true;
  auto = false;
  lastTouch = performance.now();
}

function release() {
  if (auto) return;
  holding = false;
  lastTouch = performance.now();
}

pill.addEventListener('pointerdown', function (e) {
  if (e.button) return;
  press();
  try { pill.setPointerCapture(e.pointerId); } catch (err) {}
});
pill.addEventListener('pointerup', release);
pill.addEventListener('pointercancel', release);
pill.addEventListener('lostpointercapture', release);
pill.addEventListener('contextmenu', function (e) { e.preventDefault(); });
pill.addEventListener('keydown', function (e) {
  if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); if (!e.repeat) press(); }
});
pill.addEventListener('keyup', function (e) {
  if (e.key === ' ' || e.key === 'Enter') release();
});
pill.addEventListener('blur', release);

el.addEventListener('pointerenter', function () {
  hover = true;
  if (auto) { auto = false; holding = false; } // hand control to the user
});
el.addEventListener('pointerleave', function () {
  hover = false;
  idleAt = performance.now();
});

var ro = null;
if (typeof ResizeObserver !== 'undefined') { ro = new ResizeObserver(measure); ro.observe(el); }
window.addEventListener('resize', measure);
if (document.fonts && document.fonts.ready) document.fonts.ready.then(function () { if (!dead) measure(); });

function dispose() {
  dead = true;
  if (raf) cancelAnimationFrame(raf);
  if (ro) ro.disconnect();
  window.removeEventListener('resize', measure);
}

measure();
pill.style.width = w + 'px';
raf = requestAnimationFrame(frame);
return dispose;

css:
.m-liquid-glass-stats {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: #f7f7f8;
  color: #111113;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Inter", "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}
.m-liquid-glass-stats__app {
  position: absolute;
  inset: 0;
  box-sizing: border-box;
  width: min(100%, 440px);
  height: min(100%, 330px);
  margin: auto;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.m-liquid-glass-stats__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex: none;
}
.m-liquid-glass-stats__trigger {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  font-size: 21px;
  font-weight: 750;
  line-height: 1.1;
  letter-spacing: -0.035em;
  cursor: pointer;
  border-radius: 6px;
  outline: none;
  transform-origin: 0 50%;
  transition: transform 0.25s cubic-bezier(0.3, 1.4, 0.4, 1);
}
.m-liquid-glass-stats__trigger:active,
.m-liquid-glass-stats__trigger[aria-expanded="true"] {
  transform: scale(0.96);
}
.m-liquid-glass-stats__trigger:focus-visible {
  box-shadow: 0 0 0 2px rgba(0, 0, 0, 0.2);
}
.m-liquid-glass-stats__trigger svg {
  width: 9px;
  height: 13px;
  fill: none;
  stroke: #b3b3bb;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.m-liquid-glass-stats__date {
  margin-top: 2px;
  font-size: 10.5px;
  line-height: 13px;
  color: #8e8e93;
}
.m-liquid-glass-stats__tools {
  display: flex;
  gap: 6px;
}
.m-liquid-glass-stats__tools span {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: #ededf0;
}
.m-liquid-glass-stats__tools svg {
  width: 13px;
  height: 13px;
  fill: none;
  stroke: #111113;
  stroke-width: 1.8;
  stroke-linecap: round;
}
.m-liquid-glass-stats__card {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  padding: 11px 12px 9px;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 0 0 0.5px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.04), 0 10px 24px -14px rgba(0, 0, 0, 0.16);
  transform: scale(calc(1 - var(--m, 0) * 0.025));
  transform-origin: 50% 20%;
}
.m-liquid-glass-stats__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex: none;
}
.m-liquid-glass-stats__label {
  font-size: 11.5px;
  font-weight: 600;
  color: #8e8e93;
}
.m-liquid-glass-stats__seg {
  position: relative;
  display: flex;
  padding: 2px;
  border-radius: 999px;
  background: #ededf0;
}
.m-liquid-glass-stats__seg button {
  position: relative;
  z-index: 1;
  margin: 0;
  padding: 4px 10px;
  border: 0;
  border-radius: 999px;
  background: none;
  color: #8e8e93;
  font: inherit;
  font-size: 10.5px;
  font-weight: 600;
  line-height: 14px;
  cursor: pointer;
  outline: none;
  transition: color 0.25s ease;
}
.m-liquid-glass-stats__seg button[aria-selected="true"] {
  color: #111113;
}
.m-liquid-glass-stats__seg button:focus-visible {
  box-shadow: 0 0 0 2px rgba(0, 0, 0, 0.2);
}
.m-liquid-glass-stats__thumb {
  position: absolute;
  left: 0;
  top: 2px;
  width: 40px;
  height: calc(100% - 4px);
  border-radius: 999px;
  background: #ffffff;
  box-shadow: 0 1px 2.5px rgba(0, 0, 0, 0.14), 0 0 0 0.5px rgba(0, 0, 0, 0.05);
  transform-origin: 50% 50%;
  will-change: transform, width;
}
.m-liquid-glass-stats__count {
  display: flex;
  align-items: flex-start;
  flex: none;
  margin-top: 6px;
  font-family: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 30px;
  font-weight: 600;
  line-height: 1.15em;
  height: 1.15em;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
}
.m-liquid-glass-stats__hrs {
  display: inline-flex;
  flex: none;
  width: 2.55ch;
  overflow: hidden;
  transition: width 0.55s cubic-bezier(0.3, 1.25, 0.4, 1), opacity 0.3s ease;
}
.m-liquid-glass-stats__count.is-nohrs .m-liquid-glass-stats__hrs {
  width: 0;
  opacity: 0;
}
.m-liquid-glass-stats__digit {
  display: inline-block;
  flex: none;
  width: 1ch;
  height: 1.15em;
  overflow: hidden;
  text-align: center;
}
.m-liquid-glass-stats__reel {
  display: block;
  transform: translateY(calc(var(--v, 0) * -1.15em));
  transition: transform 0.7s cubic-bezier(0.25, 1.32, 0.35, 1);
  will-change: transform;
}
.m-liquid-glass-stats__reel b {
  display: block;
  height: 1.15em;
  font-weight: inherit;
}
.m-liquid-glass-stats__unit {
  flex: none;
}
.m-liquid-glass-stats__cap {
  flex: none;
  margin-top: 1px;
  font-size: 10.5px;
  line-height: 13px;
  color: #a1a1aa;
}
.m-liquid-glass-stats__cap span {
  display: inline-block;
  transition: opacity 0.18s ease, transform 0.3s cubic-bezier(0.2, 0.9, 0.3, 1);
}
.m-liquid-glass-stats__cap span.is-out {
  opacity: 0;
  transform: translateY(3px);
}
.m-liquid-glass-stats__chart {
  position: relative;
  flex: 1 1 auto;
  min-height: 40px;
  margin-top: 5px;
}
.m-liquid-glass-stats__chart canvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}
.m-liquid-glass-stats__menu {
  position: absolute;
  left: 10px;
  top: 36px;
  z-index: 3;
  box-sizing: border-box;
  width: 188px;
  padding: 5px;
  border-radius: 17px;
  background: rgba(255, 255, 255, 0.56);
  -webkit-backdrop-filter: blur(18px) saturate(190%);
  backdrop-filter: blur(18px) saturate(190%);
  box-shadow: 0 0 0 0.5px rgba(0, 0, 0, 0.07), 0 20px 44px -10px rgba(22, 22, 44, 0.26), 0 4px 12px rgba(22, 22, 44, 0.08);
  transform-origin: 16px 0;
  transform: scale(0.5);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  will-change: transform, opacity, filter;
}
.m-liquid-glass-stats__menu::before {
  content: "";
  position: absolute;
  inset: 0;
  padding: 1px;
  border-radius: inherit;
  background: linear-gradient(140deg, #ffffff, rgba(255, 255, 255, 0.25) 34%, rgba(255, 255, 255, 0.12) 62%, rgba(255, 255, 255, 0.85));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
  pointer-events: none;
}
.m-liquid-glass-stats__menu.is-open {
  pointer-events: auto;
}
.m-liquid-glass-stats__menu button {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  box-sizing: border-box;
  width: 100%;
  margin: 0;
  padding: 7px 8px;
  border: 0;
  border-radius: 12px;
  background: transparent;
  color: #1c1c1e;
  font: inherit;
  font-size: 12.5px;
  font-weight: 600;
  line-height: 16px;
  text-align: left;
  cursor: pointer;
  outline: none;
  opacity: 0;
  transform: translateY(-5px);
  transition: opacity 0.12s ease, transform 0.12s ease, background-color 0.18s ease;
}
.m-liquid-glass-stats__menu.is-open button {
  opacity: 1;
  transform: none;
  transition: opacity 0.22s ease, transform 0.42s cubic-bezier(0.3, 1.35, 0.4, 1), background-color 0.18s ease;
}
.m-liquid-glass-stats__menu.is-open button:nth-child(1) { transition-delay: 0.04s, 0.04s, 0s; }
.m-liquid-glass-stats__menu.is-open button:nth-child(2) { transition-delay: 0.08s, 0.08s, 0s; }
.m-liquid-glass-stats__menu.is-open button:nth-child(3) { transition-delay: 0.12s, 0.12s, 0s; }
.m-liquid-glass-stats__menu button:hover,
.m-liquid-glass-stats__menu button:focus-visible {
  background: rgba(120, 120, 128, 0.1);
}
.m-liquid-glass-stats__menu button.is-active {
  background: rgba(120, 120, 128, 0.16);
}
.m-liquid-glass-stats__menu button > svg {
  flex: none;
  width: 14px;
  height: 14px;
  fill: #8e8e93;
}
.m-liquid-glass-stats__menu em {
  margin-left: auto;
  font-style: normal;
  font-size: 11px;
  font-weight: 500;
  color: #8e8e93;
  font-variant-numeric: tabular-nums;
}
.m-liquid-glass-stats__menu i {
  display: grid;
  place-items: center;
  flex: none;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  background: #111113;
  transform: scale(0);
  transition: transform 0.4s cubic-bezier(0.3, 1.5, 0.4, 1);
}
.m-liquid-glass-stats__menu button.is-active i {
  transform: scale(1);
}
.m-liquid-glass-stats__menu i svg {
  width: 9px;
  height: 9px;
  fill: none;
  stroke: #ffffff;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

