var el = root.querySelector('.m-liquid-glass-stats');
if (!el) return;
var P = 'm-liquid-glass-stats__';
var pick = function (n) { return el.querySelector('.' + P + n); };
var app = pick('app'), seg = pick('seg'), thumb = pick('thumb'), count = pick('count');
var capIn = pick('cap').firstElementChild, chart = pick('chart'), trigger = pick('trigger'), menu = pick('menu');
var tabs = seg.querySelectorAll('button'), items = menu.querySelectorAll('button');
var cv = chart.querySelector('canvas'), ctx = cv.getContext('2d');
if (!ctx) return;

var MODES = [
  { h: 0, m: 42, cap: 'Today · goal 60 min', peak: 7, tag: '12m', avg: 0,
    vals: [0.1, 0.28, 0.16, 0.6, 0.34, 0.08, 0.2, 0.9, 0.46, 0.24, 0.38, 0.12],
    ticks: [[0, '8a'], [4, '12p'], [8, '4p'], [11, '8p']] },
  { h: 3, m: 48, cap: '17–23 Nov · avg 33 min/day', peak: 4, tag: '58m', avg: 0,
    vals: [0.2, 0.52, 0.18, 0.5, 0.92, 0.76, 0.1],
    ticks: [[0, 'Tue'], [1, 'Wed'], [2, 'Thu'], [3, 'Fri'], [4, 'Sat'], [5, 'Sun'], [6, 'Today']] },
  { h: 8, m: 19, cap: 'November · avg 17 min/day', peak: 14, tag: '45m', avg: 0.36,
    vals: [0.3, 0.42, 0.04, 0.2, 0.34, 0.5, 0.46, 0.1, 0.04, 0.24, 0.3, 0.36, 0.18, 0.44, 0.92, 0.3, 0.22, 0.4, 0.12, 0.36, 0.44, 0.4, 0.3, 0.06, 0.03, 0.03, 0.03, 0.03, 0.03, 0.03],
    ticks: [[0, 'Nov 1'], [7, '8'], [14, '15'], [21, '22'], [29, '30']] }
];
var N = 30, F = 5;                 // bar slots, fields per bar: x, w, h, alpha, peak-mix
var TOP = 17, FOOT = 14;           // room for the peak tag above / tick labels below
var mode = 1, prevMode = 1, changeAt = -1e9;
var W = 0, H = 0, K = 1, dpr = 1, tries = 0;
var val = new Float32Array(N * F), vel = new Float32Array(N * F), tar = new Float32Array(N * F), nxt = new Float32Array(N * F);
var due = new Float64Array(N);
var tag = { x: 0, y: 0, vx: 0, vy: 0, tx: 0, ty: 0, text: MODES[1].tag, at: 0 };
var avg = { y: 0, a: 0, ty: 0, ta: 0 };
var th = { x: 0, w: 0, vx: 0, vw: 0, tx: 0, tw: 0, ready: false };
var mn = { v: 0, vel: 0, open: false, shown: -1 };
var raf = 0, last = 0, busyUntil = 0, seen = false, dead = false;
var hover = false, resumeAt = 0, capTimer = 0, closeTimer = 0, autoTimer = 0, autoStep = 0;

function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }

// ---------- rolling counter ----------
function mk(tag_, cls) { var n = document.createElement(tag_); if (cls) n.className = P + cls; return n; }
function reel() {
  var d = mk('span', 'digit'), r = mk('span', 'reel');
  for (var i = 0; i < 10; i++) { var b = document.createElement('b'); b.textContent = i; r.appendChild(b); }
  d.appendChild(r);
  d.setAttribute('aria-hidden', 'true');
  return d;
}
function unit(t) { var u = mk('span', 'unit'); u.textContent = t; u.setAttribute('aria-hidden', 'true'); return u; }
var hrs = mk('span', 'hrs'), dH = reel(), dT = reel(), dO = reel();
count.textContent = '';
hrs.appendChild(dH); hrs.appendChild(unit('h'));
count.appendChild(hrs); count.appendChild(dT); count.appendChild(dO); count.appendChild(unit('m'));
[dH, dT, dO].forEach(function (d, i) { d.firstChild.style.transitionDelay = (i * 60) + 'ms'; });
function setCount(m) {
  dH.firstChild.style.setProperty('--v', m.h);
  dT.firstChild.style.setProperty('--v', Math.floor(m.m / 10));
  dO.firstChild.style.setProperty('--v', m.m % 10);
  count.classList.toggle('is-nohrs', !m.h);
  count.setAttribute('aria-label', (m.h ? m.h + 'h ' : '') + m.m + 'm');
}
function setCap(text, instant) {
  clearTimeout(capTimer);
  if (instant) { capIn.textContent = text; capIn.classList.remove('is-out'); return; }
  capIn.classList.add('is-out');
  capTimer = setTimeout(function () { capIn.textContent = text; capIn.classList.remove('is-out'); }, 160);
}

// ---------- chart ----------
function layout(i, out) {
  var m = MODES[i], n = m.vals.length, slot = W / n, bw = Math.min(24, slot * 0.62);
  var s30 = W / N, b30 = Math.min(24, s30 * 0.62), bh = H - FOOT - TOP;
  for (var j = 0; j < N; j++) {
    var o = j * F;
    if (j < n) {
      out[o] = j * slot + (slot - bw) / 2; out[o + 1] = bw; out[o + 2] = Math.max(2, m.vals[j] * bh);
      out[o + 3] = 1; out[o + 4] = j === m.peak ? 1 : 0;
    } else { // unused slots sink where the dense layout would put them
      out[o] = j * s30 + (s30 - b30) / 2; out[o + 1] = b30; out[o + 2] = 0; out[o + 3] = 0; out[o + 4] = 0;
    }
  }
}
function retarget(instant) {
  if (!W) return;
  layout(mode, nxt);
  var now = performance.now(), m = MODES[mode];
  var n = Math.max(m.vals.length, MODES[prevMode].vals.length), gap = n > 14 ? 9 : 24;
  for (var j = 0; j < N; j++) due[j] = instant ? -1 : now + Math.min(j, n) * gap; // left-to-right stagger
  if (instant) { val.set(nxt); tar.set(nxt); vel.fill(0); }
  var o = m.peak * F, base = H - FOOT;
  tag.tx = nxt[o] + nxt[o + 1] / 2; tag.ty = base - nxt[o + 2] - 4; tag.text = m.tag;
  tag.at = instant ? now - 1000 : now + 170;
  avg.ta = m.avg ? 1 : 0;
  if (m.avg) avg.ty = base - m.avg * (base - TOP);
  if (instant) { tag.x = tag.tx; tag.y = tag.ty; tag.vx = tag.vy = 0; avg.a = avg.ta; avg.y = avg.ty; }
}
function rr(x, y, w, h, r) {
  r = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}
function ticks(i, a) {
  if (a <= 0.01) return;
  var m = MODES[i], slot = W / m.vals.length;
  for (var t = 0; t < m.ticks.length; t++) {
    var tk = m.ticks[t], strong = tk[1] === 'Today';
    ctx.font = (strong ? '700' : '500') + ' 8.5px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
    var tw = ctx.measureText(tk[1]).width;
    ctx.globalAlpha = a;
    ctx.fillStyle = strong ? '#111113' : '#a1a1aa';
    ctx.fillText(tk[1], clamp(tk[0] * slot + slot / 2, tw / 2, W - tw / 2), H - 3);
  }
}
function draw(now) {
  if (!W) return;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, W, H);
  var base = H - FOOT, j, o;
  if (avg.a > 0.01) {
    ctx.globalAlpha = avg.a * 0.9;
    ctx.strokeStyle = '#c7c7cf'; ctx.lineWidth = 1; ctx.setLineDash([2, 3]);
    ctx.beginPath(); ctx.moveTo(0, Math.round(avg.y) + 0.5); ctx.lineTo(W, Math.round(avg.y) + 0.5); ctx.stroke();
    ctx.setLineDash([]);
  }
  for (j = 0; j < N; j++) {
    o = j * F;
    var a = clamp(val[o + 3], 0, 1), h = val[o + 2];
    if (a < 0.01 || h < 0.4) continue;
    var k = clamp(val[o + 4], 0, 1);
    ctx.globalAlpha = a;
    ctx.fillStyle = 'rgb(' + Math.round(200 + 25 * k) + ',' + Math.round(200 - 171 * k) + ',' + Math.round(207 - 91 * k) + ')'; // #c8c8cf -> #e11d74
    rr(val[o], base - h, val[o + 1], h, 3);
    ctx.fill();
  }
  ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
  var f = clamp((now - changeAt) / 340, 0, 1);
  if (f < 1 && prevMode !== mode) ticks(prevMode, 1 - clamp(f * 2.2, 0, 1));
  ticks(mode, clamp(f * 2.2 - 1, 0, 1));
  var ta = clamp((now - tag.at) / 220, 0, 1);
  if (ta > 0.01) {
    ctx.font = '700 8.5px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
    var w = ctx.measureText(tag.text).width + 10, x = clamp(tag.x - w / 2, 0.5, W - w - 0.5), y = Math.max(0.5, tag.y - 14);
    ctx.globalAlpha = ta;
    ctx.fillStyle = '#ffffff'; rr(x, y, w, 14, 5); ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.12)'; ctx.lineWidth = 0.75; ctx.stroke();
    ctx.fillStyle = '#111113'; ctx.fillText(tag.text, x + w / 2, y + 10);
  }
  ctx.globalAlpha = 1;
}

// ---------- springs ----------
function step(dt, now) {
  var j, o, i;
  for (j = 0; j < N; j++) {
    if (due[j] >= 0 && now >= due[j]) { o = j * F; for (i = 0; i < F; i++) tar[o + i] = nxt[o + i]; due[j] = -1; }
  }
  for (var n = 3, h = dt / 3; n-- > 0;) {
    for (i = 0; i < N * F; i++) { vel[i] += (-260 * (val[i] - tar[i]) - 21 * vel[i]) * h; val[i] += vel[i] * h; }
    tag.vx += (-220 * (tag.x - tag.tx) - 22 * tag.vx) * h; tag.x += tag.vx * h;
    tag.vy += (-220 * (tag.y - tag.ty) - 22 * tag.vy) * h; tag.y += tag.vy * h;
    th.vx += (-380 * (th.x - th.tx) - 28 * th.vx) * h; th.x += th.vx * h;
    th.vw += (-380 * (th.w - th.tw) - 28 * th.vw) * h; th.w += th.vw * h;
    var mk_ = mn.open ? 340 : 520, mc = mn.open ? 24 : 46, mt = mn.open ? 1 : 0;
    mn.vel += (-mk_ * (mn.v - mt) - mc * mn.vel) * h; mn.v += mn.vel * h;
  }
  var e = Math.min(1, dt * 9);
  avg.a += (avg.ta - avg.a) * e; avg.y += (avg.ty - avg.y) * e;

  if (th.ready) {
    var sp = Math.abs(th.vx);
    thumb.style.width = th.w.toFixed(2) + 'px';
    thumb.style.transform = 'translateX(' + th.x.toFixed(2) + 'px) scale(' + (1 + Math.min(0.16, sp / 2600)).toFixed(4) + ',' + (1 - Math.min(0.1, sp / 4200)).toFixed(4) + ')';
  }
  var m = Math.round(mn.v * 1000) / 1000;
  if (m !== mn.shown) {
    mn.shown = m;
    menu.style.transform = 'scale(' + (0.5 + 0.5 * m).toFixed(4) + ')';
    menu.style.opacity = clamp(m * 1.7, 0, 1).toFixed(3);
    menu.style.filter = m < 0.985 ? 'blur(' + ((1 - Math.min(1, m)) * 9).toFixed(2) + 'px)' : 'none';
    app.style.setProperty('--m', clamp(m, 0, 1).toFixed(3));
    if (!mn.open && m < 0.004) menu.style.visibility = 'hidden';
  }
}

function frame(now) {
  raf = 0;
  if (dead) return;
  if (el.isConnected) seen = true; else if (seen) { dispose(); return; }
  if (!W) measure();
  var dt = Math.min(0.034, (now - last) / 1000);
  last = now;
  if (dt > 0) { step(dt, now); draw(now); }
  if (now < busyUntil || (!W && tries++ < 240)) raf = requestAnimationFrame(frame);
}
function wake(ms) {
  if (dead) return;
  busyUntil = Math.max(busyUntil, performance.now() + (ms || 1900));
  if (!raf) { last = performance.now(); raf = requestAnimationFrame(frame); }
}

// ---------- state ----------
function thumbTarget(snap) {
  var b = tabs[mode];
  th.tx = b.offsetLeft; th.tw = b.offsetWidth;
  if (snap || !th.ready) { th.x = th.tx; th.w = th.tw; th.vx = th.vw = 0; th.ready = th.tw > 0; }
}
function setMode(i, instant) {
  if (i === mode && !instant) return;
  prevMode = instant ? i : mode; mode = i; changeAt = instant ? -1e9 : performance.now();
  for (var t = 0; t < tabs.length; t++) tabs[t].setAttribute('aria-selected', t === i ? 'true' : 'false');
  thumbTarget(instant);
  setCount(MODES[i]);
  setCap(MODES[i].cap, instant);
  retarget(instant);
  wake();
}
function setMenu(open) {
  clearTimeout(closeTimer);
  if (mn.open === open) return;
  mn.open = open;
  menu.classList.toggle('is-open', open);
  menu.setAttribute('aria-hidden', open ? 'false' : 'true');
  trigger.setAttribute('aria-expanded', open ? 'true' : 'false');
  if (open) menu.style.visibility = 'visible';
  wake(1400);
}
function measure() {
  var w = el.clientWidth, h = el.clientHeight;
  if (!w || !h) return;
  K = Math.max(1, Math.min(1.4, Math.min(w / 440, h / 330)));
  app.style.transform = K > 1.001 ? 'scale(' + K.toFixed(3) + ')' : '';
  var cw = chart.clientWidth, ch = chart.clientHeight;
  if (!cw || !ch) return;
  dpr = Math.min(3, (window.devicePixelRatio || 1) * K);
  W = cw; H = ch;
  cv.width = Math.round(cw * dpr); cv.height = Math.round(ch * dpr);
  thumbTarget(true);
  retarget(true);
  wake(400);
}

// ---------- input ----------
function touch(ms) { resumeAt = performance.now() + ms; }
Array.prototype.forEach.call(tabs, function (b, i) {
  b.addEventListener('click', function () { touch(6000); setMode(i); });
});
trigger.addEventListener('click', function () { touch(6000); setMenu(!mn.open); });
Array.prototype.forEach.call(items, function (it) {
  it.addEventListener('click', function () {
    touch(6000);
    Array.prototype.forEach.call(items, function (o) {
      o.classList.toggle('is-active', o === it);
      o.setAttribute('aria-checked', o === it ? 'true' : 'false');
    });
    clearTimeout(closeTimer);
    closeTimer = setTimeout(function () { setMenu(false); }, 220);
  });
});
el.addEventListener('pointerdown', function (e) {
  touch(6000);
  if (mn.open && !menu.contains(e.target) && !trigger.contains(e.target)) setMenu(false);
});
el.addEventListener('keydown', function (e) { if (e.key === 'Escape') setMenu(false); });
el.addEventListener('pointerenter', function () { hover = true; });
el.addEventListener('pointerleave', function () { hover = false; touch(2200); });

// ---------- ambient demo: Month -> Day -> glass menu -> Week ----------
var SCRIPT = [
  function () { setMode(2); return 2500; },
  function () { setMode(0); return 2300; },
  function () { setMenu(true); return 1700; },
  function () { setMenu(false); return 450; },
  function () { setMode(1); return 2500; }
];
function tick() {
  if (dead) return;
  if (seen && !el.isConnected) { dispose(); return; }
  var wait = 600;
  if (!hover && !document.hidden && performance.now() >= resumeAt && W) {
    wait = SCRIPT[autoStep % SCRIPT.length]();
    autoStep++;
  }
  autoTimer = setTimeout(tick, wait);
}

var ro = null;
if (typeof ResizeObserver !== 'undefined') { ro = new ResizeObserver(measure); ro.observe(el); }
window.addEventListener('resize', measure);

function dispose() {
  dead = true;
  if (raf) cancelAnimationFrame(raf);
  clearTimeout(autoTimer); clearTimeout(capTimer); clearTimeout(closeTimer);
  if (ro) ro.disconnect();
  window.removeEventListener('resize', measure);
}

setCount(MODES[mode]);
measure();
wake(600);
autoTimer = setTimeout(tick, 1500);
return dispose;

css:
.m-kinetic-inline-pill {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: #f8faf9;
  color: #0b0f0d;
  font-family: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Helvetica Neue", "Segoe UI", sans-serif;
  font-size: 23px;
  font-weight: 600;
  letter-spacing: -0.035em;
  line-height: 1.2;
  cursor: pointer;
  outline: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}
