var el = root.querySelector('.m-kinetic-inline-pill');
if (!el) return;
var P = '.m-kinetic-inline-pill__';
var words = el.querySelectorAll(P + 'word'), wl = words[0], wr = words[1];
var slot = el.querySelector(P + 'slot'), pill = el.querySelector(P + 'pill'), perch = el.querySelector(P + 'perch');
var bot = el.querySelector(P + 'bot'), eyes = el.querySelector(P + 'eyes');
if (!wl || !wr || !slot || !pill || !perch || !bot || !eyes) return;

var BEATS = [
  { l: 'Give your', r: 'a phone', kind: 'bot', w: 1.7 },
  { l: 'Its own', r: 'number', kind: 'num', w: 3.5 },
  { l: 'Answers', r: 'your calls', kind: 'wave', w: 2.9 }
];
var GAP = 0.28, PAD = 0.3, DOT = 0.36, TALL = 1.12, HOLD = 2300; // em units except HOLD (ms)
var beat = 0, kind = 'bot', wEm = BEATS[0].w, home = 'slot';
var open = { x: 0, v: 0, t: 0 };  // words part: 0 closed .. 1 open
var pop = { x: 0, v: 0, t: 0 };   // pill birth scale
var b = { x: 0, y: 0, vx: 0, vy: 0, s: 0.2, vs: 0, r: 0, ready: false };
var gaze = { x: 0, y: 0 }, blinkAt = 1.3, clock = 0, fs = 23;
