  pill.style.height = (DOT + Math.min(pc, 1) * (TALL - DOT)).toFixed(4) + 'em';
  pill.style.transform = 'translate(-50%,-50%) scale(' + (kind === 'bot' ? 0 : ps).toFixed(4) + ')';
