var STOPS = [[38, 38, 51], [124, 77, 255], [255, 61, 154], [255, 225, 77]];
var ORIGINS = [[0.1, 0.18], [0.9, 0.84], [0.5, 0.5], [0.92, 0.14], [0.08, 0.86]];

var LUT = [];
for (var q = 0; q <= 96; q++) {
