// Liquid mesh gradient — WebGL1 fragment shader (domain-warped fbm, one crisp silk fold)
// Uniforms: u_res (px), u_time (s), u_mouse (px, origin bottom-left), u_kick (0..1 click impulse)
precision highp float;
uniform vec2 u_res;
uniform float u_time;
uniform vec2 u_mouse;
uniform float u_kick;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float vnoise(vec2 p) {                       // quintic value noise: no visible lattice
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) {                          // 3 octaves, low gain: silk, not cloud
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 3; i++) {
    v += a * vnoise(p);
    p = mat2(0.8, -0.6, 0.6, 0.8) * p * 2.03 + 11.7;
    a *= 0.35;
  }
  return v / 0.736;
}
mat2 rot(float a) { float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }

void main() {
  float mn = min(u_res.x, u_res.y);
  vec2 p = (gl_FragCoord.xy - 0.5 * u_res) / mn;
  vec2 m = (u_mouse - 0.5 * u_res) / mn;
  float t = u_time * 0.085;

  // pointer: gaussian swirl + slight lens pinch
  vec2 d = p - m;
  float fall = exp(-dot(d, d) * 4.5);
  p = m + rot(fall * (1.15 + 2.4 * u_kick)) * d * (1.0 - 0.2 * fall);

  // two-stage domain warp, kept low-frequency so only one or two folds are on screen
  vec2 q = vec2(fbm(p * 0.6 + vec2(0.0, t)), fbm(p * 0.6 + vec2(5.2, 1.3) - t));
  vec2 r = vec2(fbm(p * 0.55 + 1.8 * q + vec2(1.7, 9.2) + 0.6 * t),
                fbm(p * 0.55 + 1.8 * q + vec2(8.3, 2.8) - 0.5 * t));
  float f = fbm(p * 0.5 + 1.9 * r + 0.3 * t);

  // slowly rotating linear bias: guarantees a fold always crosses the frame
  float ga = t * 0.7;
  float g = dot(p, vec2(cos(ga), sin(ga)));

  vec3 indigo = vec3(0.118, 0.106, 0.294);   // #1e1b4b
  vec3 violet = vec3(0.486, 0.227, 0.929);   // #7c3aed
  vec3 pink   = vec3(1.000, 0.302, 0.580);   // #ff4d94
  vec3 pearl  = vec3(0.961, 0.816, 0.996);   // #f5d0fe

  float s = f - 0.5 + 0.3 * g;                         // the fold is the s = 0 isoline
  float side = smoothstep(-0.003, 0.003, s);           // hard edge on the magenta side...

  vec3 cool = mix(violet, mix(violet, pearl, 0.62), smoothstep(0.34, 0.66, q.x));
  cool = mix(cool, pearl, smoothstep(0.52, 0.74, r.x));            // pearlescent haze
  cool = mix(cool, indigo, 0.85 * smoothstep(0.42, 0.24, r.y));    // indigo pockets

  vec3 warm = mix(pink, mix(pink, pearl, 0.5), smoothstep(0.03, 0.2, s));   // hottest at the fold
  warm = mix(warm, violet, 0.55 * smoothstep(0.12, 0.3, s));

  float sheen = exp(min(s, 0.0) * 42.0);               // ...soft exponential sheen on the cool side
  float tone = smoothstep(0.5, 0.72, vnoise(p * 0.9 + vec2(t * 1.3, 3.1)));
  cool = mix(cool, mix(pearl, indigo, tone), 0.95 * sheen);        // crease reads pearl or indigo

  vec3 col = mix(cool, warm, side);
  col += (hash(gl_FragCoord.xy + fract(u_time) * 61.0) - 0.5) * 0.016;   // dither against banding
  gl_FragColor = vec4(col, 1.0);
}

/* JS bootstrap (vanilla):
const gl = canvas.getContext('webgl');
// compile `attribute vec2 a_pos; void main(){ gl_Position = vec4(a_pos, 0., 1.); }` + the shader above,
// draw one oversized triangle: bufferData(new Float32Array([-1,-1, 3,-1, -1,3]))
// each frame: ease a pointer toward the cursor (or a slow Lissajous path when idle), decay u_kick, then
//   gl.uniform2f(uRes, w, h); gl.uniform1f(uTime, t); gl.uniform2f(uMouse, px, h - py); gl.uniform1f(uKick, k);
//   gl.drawArrays(gl.TRIANGLES, 0, 3);
// if getContext('webgl') returns null, paint drifting radial gradients on a low-res 2D canvas instead. */

