  position: absolute;
  left: 14px;
  bottom: 12px;
  font: 500 10px/1.2 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.78);
  text-shadow: 0 1px 6px rgba(30, 27, 75, 0.45);
  pointer-events: none;
}

