var host = root.querySelector('.m-luminous-beam-sweep'); if (!host) return;
var apB = host.querySelector('.m-luminous-beam-sweep__ap--bloom'), apC = host.querySelector('.m-luminous-beam-sweep__ap--core');
var sample = host.querySelector('.m-luminous-beam-sweep__type--dim span');
if (!apB || !apC || !sample) return;
var inB = apB.querySelector('.m-luminous-beam-sweep__in'), inC = apC.querySelector('.m-luminous-beam-sweep__in');
var curtains = host.querySelectorAll('.m-luminous-beam-sweep__curtain');
var streak = host.querySelector('.m-luminous-beam-sweep__type--streak');
var filt = host.querySelector('.m-luminous-beam-sweep__defs filter');
