  var fid = 'm-lbs-' + Math.random().toString(36).slice(2, 9);
  filt.setAttribute('id', fid);
  streak.style.filter = 'url(#' + fid + ')';
}

var W = 0, H = 0, AB = 0, AC = 0, dpr = 1;
var x = 0, target = 0, hover = false, clock = 0;

function fit() {
  var r = host.getBoundingClientRect();
  if (r.width < 2 || r.height < 2) return;
  var first = W === 0;
  W = r.width; H = r.height; dpr = window.devicePixelRatio || 1;
