  host.style.setProperty('--fs', '100px');
  var tw = sample.getBoundingClientRect().width || 420;
  var fs = Math.min(100 * (W * 0.74) / tw, H * 0.5);
  host.style.setProperty('--fs', fs.toFixed(2) + 'px');
  host.style.setProperty('--w', W.toFixed(2) + 'px');
  AB = W * 0.5; AC = W * 0.25;
  apB.style.width = AB.toFixed(2) + 'px'; apC.style.width = AC.toFixed(2) + 'px';
  if (blur) blur.setAttribute('stdDeviation', (fs * 0.42).toFixed(1) + ' ' + (fs * 0.008).toFixed(2));
