  border: 1px solid rgba(17, 17, 17, 0.08);
  border-radius: 0.9em;
  box-shadow: 0 1px 0 rgba(17, 17, 17, 0.02), 0 0.8em 1.6em -1.2em rgba(17, 17, 17, 0.25);
  transition: opacity 0.28s ease, border-color 0.16s ease, box-shadow 0.28s ease;
  cursor: pointer;
}
.m-bento-studio-marquee__col.is-held .m-bento-studio-marquee__card {
  opacity: 0.5;
}
.m-bento-studio-marquee__col.is-held .m-bento-studio-marquee__card.is-hot {
  opacity: 1;
}
.m-bento-studio-marquee__card.is-hot {
  z-index: 3;
  border-color: #111;
  box-shadow: 0 0 0 1px #111, 0 1.6em 2.4em -1.2em rgba(17, 17, 17, 0.42);
}
.m-bento-studio-marquee__hd {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 0.4em;
}
.m-bento-studio-marquee__hd b {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 1.16em;
  font-weight: 600;
  letter-spacing: -0.02em;
}
.m-bento-studio-marquee__hd i {
  font-family: var(--mono);
  font-size: 0.5em;
  font-style: normal;
  color: #b3b0a8;
}
.m-bento-studio-marquee__sub {
  margin-top: 0.3em;
  font-family: var(--mono);
  font-size: 0.5em;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #e5533c;
}
.m-bento-studio-marquee__demo {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.5em;
  min-height: 4.2em;
  margin: 0.8em 0 0.7em;
}
.m-bento-studio-marquee__ft {
  display: flex;
  justify-content: space-between;
  gap: 0.6em;
  padding-top: 1em;
  border-top: 1px solid rgba(17, 17, 17, 0.06);
  font-family: var(--mono);
  font-size: 0.48em;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
  color: #a29f97;
}
.m-bento-studio-marquee__ft span:first-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.m-bento-studio-marquee__foot {
  flex: none;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 1em;
  padding: 0.6em 1.2em 1em;
}
.m-bento-studio-marquee__kick {
  height: 1.3em;
  margin-bottom: 0.7em;
  font-family: var(--mono);
  font-size: 0.5em;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  white-space: nowrap;
  color: #8d8a82;
}
.m-bento-studio-marquee__h {
  font: italic 400 2em/1 "Instrument Serif", "Cormorant Garamond", "Iowan Old Style", "Times New Roman", Georgia, serif;
  letter-spacing: -0.01em;
  white-space: nowrap;
}
.m-bento-studio-marquee__pill {
  flex: none;
  padding: 0.9em 1.7em;
  border: 1px solid rgba(17, 17, 17, 0.12);
  border-radius: 99em;
  background: #f9f8f5;
  font-family: var(--mono);
  font-size: 0.48em;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  white-space: nowrap;
  color: #6f6c65;
}

/* KPI */
.m-bento-studio-marquee__kpi small {
  display: block;
  font-size: 0.55em;
  color: #8d8a82;
}
.m-bento-studio-marquee__kpi-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.4em;
  margin-top: 0.1em;
}
.m-bento-studio-marquee__kpi-row strong {
  font-size: 1.42em;
  font-weight: 700;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
}
.m-bento-studio-marquee__kpi-row em {
  padding: 0.35em 0.7em;
  border-radius: 99em;
  background: #dcfce7;
  color: #15803d;
  font-family: var(--mono);
  font-size: 0.48em;
  font-style: normal;
  font-weight: 600;
}
.m-bento-studio-marquee__spark {
  display: block;
  width: 100%;
  height: 1.9em;
  margin-top: 0.4em;
  overflow: visible;
}
.m-bento-studio-marquee__spark-l {
  fill: none;
  stroke: #3b82f6;
  stroke-width: 1.4;
  vector-effect: non-scaling-stroke;
}
.m-bento-studio-marquee__spark-a {
  fill: rgba(59, 130, 246, 0.1);
}

/* buttons + toggle pill */
.m-bento-studio-marquee__btns {
  display: flex;
  gap: 0.4em;
}
.m-bento-studio-marquee__btn {
  padding: 0.6em 1.3em;
  border: 1px solid rgba(17, 17, 17, 0.14);
  border-radius: 0.7em;
  background: #fff;
  font-size: 0.56em;
  font-weight: 600;
}
.m-bento-studio-marquee__btn--solid {
  border-color: #111;
  background: #111;
  color: #fff;
}
.m-bento-studio-marquee__sw-row {
  display: flex;
  align-items: center;
  gap: 0.6em;
  font-size: 0.56em;
  white-space: nowrap;
}
.m-bento-studio-marquee__sw {
  position: relative;
  flex: none;
  width: 2.7em;
  height: 1.5em;
  border-radius: 99em;
  background: #d9d7d0;
  transition: background 0.3s ease;
}
.m-bento-studio-marquee__sw::after {
  content: "";
  position: absolute;
  left: 0.2em;
  top: 0.2em;
  width: 1.1em;
  height: 1.1em;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.25);
  transition: transform 0.42s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.m-bento-studio-marquee.is-tick .m-bento-studio-marquee__sw {
  background: #111;
}
.m-bento-studio-marquee.is-tick .m-bento-studio-marquee__sw::after {
  transform: translateX(1.2em);
}
.m-bento-studio-marquee__input {
  padding: 0.6em 0.9em;
  border: 1px solid rgba(17, 17, 17, 0.12);
  border-radius: 0.7em;
  font-family: var(--mono);
  font-size: 0.5em;
  color: #8d8a82;
}

/* toast */
.m-bento-studio-marquee__toasts {
  position: relative;
  height: 3.7em;
}
.m-bento-studio-marquee__toasts > i {
  position: absolute;
  left: 9%;
  right: 9%;
  top: 0;
  height: 2em;
  border: 1px solid rgba(17, 17, 17, 0.08);
  border-radius: 0.6em;
  background: #fff;
}
.m-bento-studio-marquee__toasts > i + i {
  left: 4.5%;
  right: 4.5%;
  top: 0.45em;
}
.m-bento-studio-marquee__toast {
  position: absolute;
  left: 0;
  right: 0;
  top: 0.95em;
  display: flex;
  align-items: center;
  gap: 0.7em;
  padding: 0.95em 1em;
  border: 1px solid rgba(17, 17, 17, 0.1);
  border-radius: 0.9em;
  background: #fff;
  box-shadow: 0 0.6em 1.2em -0.6em rgba(17, 17, 17, 0.25);
  font-size: 0.6em;
  font-weight: 500;
  white-space: nowrap;
  transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.m-bento-studio-marquee__toast b {
  flex: none;
  width: 0.8em;
  height: 0.8em;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 0 0.28em rgba(34, 197, 94, 0.18);
}
.m-bento-studio-marquee.is-tick .m-bento-studio-marquee__toast {
  transform: translateY(-0.4em);
}

/* command menu */
.m-bento-studio-marquee__cmd {
  overflow: hidden;
  border: 1px solid rgba(17, 17, 17, 0.1);
  border-radius: 0.8em;
  font-size: 0.54em;
  white-space: nowrap;
}
.m-bento-studio-marquee__cmd-in {
  display: flex;
  align-items: center;
  gap: 0.7em;
  padding: 0.7em 0.9em;
  border-bottom: 1px solid rgba(17, 17, 17, 0.08);
  font-family: var(--mono);
  color: #a29f97;
}
.m-bento-studio-marquee__cmd kbd {
  padding: 0.15em 0.45em;
  border-radius: 0.4em;
  background: #f1efe9;
  font: inherit;
  color: #111;
}
.m-bento-studio-marquee__cmd p {
  margin: 0;
  padding: 0.55em 0.9em;
  transition: background 0.3s ease;
}
.m-bento-studio-marquee__cmd p.is-sel,
.m-bento-studio-marquee.is-tick .m-bento-studio-marquee__cmd p.is-sel + p {
  background: #f1efe9;
}
.m-bento-studio-marquee.is-tick .m-bento-studio-marquee__cmd p.is-sel {
  background: transparent;
}

/* bar + line chart */
.m-bento-studio-marquee__chart {
  display: block;
  width: 100%;
  height: 4.2em;
}
.m-bento-studio-marquee__chart rect {
  fill: #c7d9fb;
}
.m-bento-studio-marquee__chart polyline {
  fill: none;
  stroke: #7c5cff;
  stroke-width: 1.4;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

/* theme pills */
.m-bento-studio-marquee__pills {
  display: flex;
  gap: 0.35em;
}
.m-bento-studio-marquee__pills span {
  padding: 0.45em 0.9em;
  border-radius: 99em;
  font-size: 0.45em;
  font-weight: 600;
  color: #fff;
}
.m-bento-studio-marquee__swatch {
  display: flex;
  align-items: center;
  gap: 0.35em;
}
.m-bento-studio-marquee__swatch i {
  flex: none;
  width: 0.8em;
  height: 0.8em;
  border-radius: 50%;
}
.m-bento-studio-marquee__swatch u {
  flex: 1;
  height: 0.6em;
  border-radius: 99em;
  background: linear-gradient(90deg, #4f46e5, #ec4899);
  transform-origin: 0 50%;
  transition: transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}
.m-bento-studio-marquee.is-tick .m-bento-studio-marquee__swatch u {
  transform: scaleX(0.55);
}

/* icons */
.m-bento-studio-marquee__icons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.7em 0.4em;
  justify-items: center;
}
.m-bento-studio-marquee__icons svg {
  width: 1.5em;
  height: 1.5em;
  fill: none;
  stroke: #111;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: stroke 0.4s ease;
}
.m-bento-studio-marquee.is-tick .m-bento-studio-marquee__icons svg:nth-child(3) {
  stroke: #e5533c;
}

/* dropdown */
.m-bento-studio-marquee__dd {
  font-size: 0.54em;
  white-space: nowrap;
}
.m-bento-studio-marquee__dd-btn {
  display: inline-block;
  padding: 0.5em 0.9em;
  border: 1px solid rgba(17, 17, 17, 0.14);
  border-radius: 0.6em;
  font-weight: 500;
}
.m-bento-studio-marquee__menu {
  margin: 0.5em 0 0 1.4em;
  padding: 0.3em;
  border: 1px solid rgba(17, 17, 17, 0.1);
  border-radius: 0.7em;
  background: #fff;
  box-shadow: 0 0.8em 1.4em -0.8em rgba(17, 17, 17, 0.25);
}
.m-bento-studio-marquee__menu p {
  margin: 0;
  padding: 0.4em 0.7em;
  border-radius: 0.4em;
}
.m-bento-studio-marquee__menu p.is-sel {
  background: #eef2ff;
}
.m-bento-studio-marquee__menu p.is-red {
  color: #dc2626;
}

/* beam */
.m-bento-studio-marquee__beam {
  display: block;
  width: 100%;
  height: 4.2em;
}
.m-bento-studio-marquee__beam path {
  fill: none;
  stroke: #ecc9bf;
  stroke-width: 0.8;
}
.m-bento-studio-marquee__beam text {
  font-size: 6px;
  font-weight: 600;
  text-anchor: middle;
  fill: #cfccc4;
  transition: fill 1.1s ease;
}
.m-bento-studio-marquee.is-tick .m-bento-studio-marquee__beam text {
  fill: #111;
}

/* skill doc */
.m-bento-studio-marquee__doc {
  display: flex;
  flex-direction: column;
  gap: 0.45em;
  padding: 0.7em 0.8em;
  border-radius: 0.6em;
  background: #f3eee4;
}
.m-bento-studio-marquee__doc small {
  font-family: var(--mono);
  font-size: 0.5em;
  color: #6b6860;
}
.m-bento-studio-marquee__doc i,
.m-bento-studio-marquee__doc u {
  height: 0.3em;
  border-radius: 99em;
  background: #ddd6c8;
}
.m-bento-studio-marquee__doc i {
  width: 78%;
  background: #e5533c;
  transition: width 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}
.m-bento-studio-marquee.is-tick .m-bento-studio-marquee__doc i {
  width: 52%;
}

/* utility block */
.m-bento-studio-marquee__tw {
  overflow: hidden;
  font-family: var(--mono);
  font-size: 0.46em;
  white-space: nowrap;
  color: #0ea5e9;
}
.m-bento-studio-marquee__tw-box {
  align-self: center;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 0.35em;
  width: 62%;
  height: 3em;
  border-radius: 0.8em;
  background: #bae6fd;
  transition: border-radius 0.6s ease, background 0.6s ease;
}
.m-bento-studio-marquee__tw-box i {
  width: 46%;
  height: 0.35em;
  border-radius: 99em;
  background: #0284c7;
}
.m-bento-studio-marquee__tw-box i + i {
  width: 30%;
  background: #fff;
}
.m-bento-studio-marquee.is-tick .m-bento-studio-marquee__tw-box {
  border-radius: 1.5em;
  background: #7dd3fc;
}

/* drawer */
.m-bento-studio-marquee__phone {
  position: relative;
  align-self: center;
  width: 3.6em;
  height: 4.4em;
  overflow: hidden;
  border: 0.22em solid #111;
  border-radius: 0.8em;
  background: #e7e5df;
}
.m-bento-studio-marquee__sheet {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 62%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.3em;
  padding-top: 0.35em;
  border-radius: 0.5em 0.5em 0 0;
  background: #fff;
  transition: transform 0.7s cubic-bezier(0.32, 0.72, 0, 1);
}
.m-bento-studio-marquee__sheet i {
  width: 30%;
  height: 0.2em;
  border-radius: 99em;
  background: #c9c6be;
}
.m-bento-studio-marquee__sheet u {
  width: 70%;
  height: 0.22em;
  border-radius: 99em;
  background: #e7e5df;
}
.m-bento-studio-marquee.is-tick .m-bento-studio-marquee__sheet {
  transform: translateY(58%);
}

