var COPIES = 3, S = 1;
var cols = [];
for (var ci = 0; ci < 3; ci++) {
  var track = colEls[ci].querySelector('.m-bento-studio-marquee__track');
  var html = SETS[ci].join(''), all = '';
  for (var k = 0; k < COPIES; k++) all += html;
