host.addEventListener('pointerover', function (ev) { inside = true; pick(ev); });
host.addEventListener('pointerdown', function (ev) { inside = true; pick(ev); });
host.addEventListener('pointerleave', function () { inside = false; lastUser = performance.now(); cool(); });
host.addEventListener('pointercancel', function () { inside = false; cool(); });

function autoSpot(now) {
